import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Navbar from './components/Navbar'; 
import Footer from './components/Footer';
import Home from './pages/Home';
import About from './pages/About';
import Services from './pages/Services'; 
import Investor from './pages/InvestorRelation'; 
import Gallery from './pages/Gallery'; 
import Branches from './pages/Branches';
import DynamicSection from './components/DynamicSection'; // Import your new component


function App() {
  return (
    <Router>
      <div className="App">
        <Navbar />
        
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/about" element={<About />} />
          <Route path="/services" element={<Services />} />
          
          {/* Option A: Keep your existing Investor page */}
          <Route path="/investor-relations" element={<Investor />} />
          
          {/* Option B: Create a new page for Loans & Reports */}
          <Route path="/apply" element={
            <div className="container" style={{ padding: '50px 20px' }}>
              <DynamicSection category="loan" title="Loan Application Center" />
              <hr />
              <DynamicSection category="report" title="Financial Reports" />
            </div>
          } />

          <Route path="/gallery" element={<Gallery />} />
          <Route path="/branches" element={<Branches />} />
          
        </Routes>

        <Footer />
      </div>
    </Router>
  );
}

export default App;
